INSERT INTO Spell (SpellID, ClientEffect, Icon, Name, Description, Target, Range, Power, CastTime, Damage, DamageType, Type, Duration, Frequency, Pulse, PulsePower, Radius, RecastDelay, ResurrectHealth, ResurrectMana, Value, Concentration, LifeDrainReturn, AmnesiaChance, Message1, Message2, Message3, Message4, InstrumentRequirement, SpellGroup, EffectGroup, SubSpellID, MoveCast, Uninterruptible, IsFocus, SharedTimerGroup, IsPrimary, IsSecondary, AllowBolt, PackageID, TooltipId, LastTimeRowUpdated, Spell_ID) VALUES (64200, 1517, 1517, 'Royal Might', 'Increases target''s Str/Con by 69', 'Realm', 1000, 0, 3.0, 0.0, 0, 'StrengthConstitutionBuff', 1200, 0, 0, 0, 0, 0, 0, 0, 69.0, 0, 0, 0, 'You feel stronger!', '{0} feels stronger!', 'Your strength returns to normal.', '{0}''s extra strength fades.', 0, 1511, 204, 0, 0, 0, 0, 0, 0, 0, 0, 'King_Fealty', 20800, '2026-10-25 00:00:00', '64200');
